const geminiResp = $input.first().json;
const prevData = $('When Executed by Another Workflow').first().json;
const DEFAULT_REPLY = "Thanks for reaching out to Chinmay Astro! If you'd like another Vedic astrology reading with Dr. Chinmay, just reply REBOOK and we'll help you get started.";
const raw = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text?.trim();
let validUserMessage = true;            // fail-open default
let reply = (raw && raw.length) ? raw : DEFAULT_REPLY;
try {
  if (raw) {
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed === 'object') {
      if (typeof parsed.valid_user_message === 'boolean') validUserMessage = parsed.valid_user_message;
      reply = (typeof parsed.response === 'string' && parsed.response.trim()) ? parsed.response.trim() : DEFAULT_REPLY;
    }
  }
} catch (e) {
  // malformed JSON → fail-open: treat as valid, send raw text (or default). Never block on a parse glitch.
  validUserMessage = true;
  reply = (raw && raw.length) ? raw : DEFAULT_REPLY;
}
return [{ json: { phoneNumber: prevData.phoneNumber, valid_user_message: validUserMessage, geminiReply: reply } }];

return [{
  json: {
    phoneNumber: $json.phoneNumber,
    messageType: 'text',
    messageContent: '✍️ Thanks for choosing to share your feedback! Please type your thoughts about the consultation and send them — we appreciate every word!'
  }
}];

const d = $('Extract Gemini Reply').first().json;
return [{ json: {
  phoneNumber: d.phoneNumber,
  messageType: 'interactive',
  interactivePayload: {
    type: 'button',
    body: { text: d.geminiReply },
    action: { buttons: [
      { type: 'reply', reply: { id: 'btn_feedback', title: 'Leave Feedback' } },
      { type: 'reply', reply: { id: 'btn_rebook', title: 'Book Again' } },
      { type: 'reply', reply: { id: 'btn_done', title: 'Done, thanks' } }
    ] }
  }
} }];

